(function(){
"use strict";
EL.registerMod({
  id:"crimson-hud",
  name:"Crimson HUD",
  version:"1.0.0",
  author:"Talon",
  description:"Compact FPS, keystrokes, and CPS overlays",
  enabled:true,
  config:[
    {key:"showFPS",label:"FPS and frame time",type:"bool",def:true},
    {key:"showKeys",label:"Keystrokes",type:"bool",def:true},
    {key:"showCPS",label:"Clicks per second",type:"bool",def:true}
  ]
},function(api){
  var style=document.getElementById("crimson-hud-style");
  if(!style){
    style=document.createElement("style");
    style.id="crimson-hud-style";
    style.textContent=".cr-hud-box{box-sizing:border-box;min-width:94px;padding:7px 9px;background:rgba(13,10,13,.82);border:1px solid rgba(202,57,76,.75);border-radius:3px;color:#f4e8e8;font:11px/1.45 ui-monospace,monospace;text-shadow:0 1px 2px #000;box-shadow:0 3px 14px #0007;pointer-events:none}.cr-hud-brand{margin-bottom:4px;color:#f17b86;font-weight:900;letter-spacing:.14em;font-size:9px}.cr-hud-line{display:flex;justify-content:space-between;gap:13px;color:#beaeb2}.cr-hud-line b{color:#fff;font-weight:700}.cr-keyboard{display:grid;grid-template-columns:repeat(3,24px);gap:3px;width:max-content;padding:5px;background:rgba(13,10,13,.82);border:1px solid rgba(202,57,76,.75);border-radius:3px;box-shadow:0 3px 14px #0007;pointer-events:none}.cr-key{height:22px;display:grid;place-items:center;border:1px solid #79515a;border-radius:2px;background:linear-gradient(#3b2930,#20171c);color:#f4dfe2;font:10px ui-monospace,monospace}.cr-key.on{color:white;border-color:#ed7782;background:linear-gradient(#a82b41,#66192c);box-shadow:0 0 8px #d73e5555}.cr-key.empty{visibility:hidden}";
    document.head.appendChild(style);
  }
  var widgets=[];
  var stopTimer=null;
  var offMouse=null;
  var offEnter=null;
  var offExit=null;
  var offArrange=null;
  var clicks=[];
  var inWorld=!!EL.game.inWorld();
  var config=function(k){return api.config.get(k)!==false;};
  function makeBox(anchor,id,content){
    var node=document.createElement("div");
    node.className="cr-hud-box";
    node.innerHTML=content;
    api.hud.register(id,node,{anchor:anchor});
    widgets.push({id:id,node:node});
    return node;
  }
  var stats=makeBox("tr","stats","<div class='cr-hud-brand'>CRIMSON / LIVE</div><div class='cr-hud-line'><span>FPS</span><b data-fps>--</b></div><div class='cr-hud-line'><span>FRAME</span><b data-ms>-- ms</b></div>");
  var cps=makeBox("tr","cps","<div class='cr-hud-brand'>INPUT</div><div class='cr-hud-line'><span>LEFT</span><b data-left>0 CPS</b></div><div class='cr-hud-line'><span>RIGHT</span><b data-right>0 CPS</b></div>");
  var keys=document.createElement("div");
  keys.className="cr-keyboard";
  keys.innerHTML="<i class='cr-key empty'></i><i class='cr-key' data-key='KeyW'>W</i><i class='cr-key empty'></i><i class='cr-key' data-key='KeyA'>A</i><i class='cr-key' data-key='KeyS'>S</i><i class='cr-key' data-key='KeyD'>D</i><i class='cr-key' data-key='Space' style='grid-column:1/4'>SPACE</i>";
  api.hud.register("keystrokes",keys,{anchor:"bl"});
  widgets.push({id:"keystrokes",node:keys});
  offMouse=api.events.on("input:mouse",function(ev){
    if(!ev || ev.down!==true) return;
    if(ev.button===0 || ev.button===2) clicks.push({t:Date.now(),button:ev.button});
  });
  function update(){
    var now=Date.now();
    clicks=clicks.filter(function(c){return now-c.t<1000;});
    var left=clicks.filter(function(c){return c.button===0;}).length;
    var right=clicks.filter(function(c){return c.button===2;}).length;
    stats.style.display=(inWorld && config("showFPS"))?"":"none";
    cps.style.display=(inWorld && config("showCPS"))?"":"none";
    keys.style.display=(inWorld && config("showKeys"))?"":"none";
    stats.querySelector("[data-fps]").textContent=String(EL.performance.fps()||0);
    var ms=EL.performance.frameMs();
    stats.querySelector("[data-ms]").textContent=(ms>0?ms.toFixed(1):"--")+" ms";
    cps.querySelector("[data-left]").textContent=left+" CPS";
    cps.querySelector("[data-right]").textContent=right+" CPS";
    var pressed=keys.querySelectorAll("[data-key]");
    for(var i=0;i<pressed.length;i++){
      var code=pressed[i].getAttribute("data-key");
      pressed[i].classList.toggle("on",EL.input.isDown(code));
    }
  }
  offEnter=api.events.on("game:world-enter",function(){inWorld=true;});
  offExit=api.events.on("game:world-exit",function(){inWorld=false;});
  offArrange=api.events.on("hud:arrange",function(ev){
    var pointer=ev && ev.on ? "auto" : "none";
    widgets.forEach(function(w){w.node.style.pointerEvents=pointer;});
  });
  stopTimer=EL.performance.every(125,update);
  update();
  return {onDisable:function(){
    if(stopTimer)stopTimer();
    if(offMouse)offMouse();
    if(offEnter)offEnter();
    if(offExit)offExit();
    if(offArrange)offArrange();
    widgets.forEach(function(w){api.hud.unregister(w.id);});
  }};
});
})();

(function(){
"use strict";
EL.registerMod({
  id:"crimson-sprint",
  name:"Toggle Sprint",
  version:"1.0.0",
  author:"Talon",
  description:"Hold sprint with Ctrl + Shift + G",
  enabled:false
},function(api){
  var active=false;
  function setSprint(value){
    active=!!value;
    EL.movement.sprint(active);
    EL.toast(active?"Toggle Sprint enabled":"Toggle Sprint disabled",1300);
  }
  var unbind=EL.input.bind("ctrl+shift+g",function(){setSprint(!active);});
  var offExit=api.events.on("game:world-exit",function(){if(active)setSprint(false);});
  return {onDisable:function(){
    if(unbind)unbind();
    if(offExit)offExit();
    if(active)EL.movement.sprint(false);
    active=false;
  }};
});
})();

(function(){
"use strict";
EL.registerMod({
  id:"crimson-crosshair",
  name:"Crimson Crosshair",
  version:"1.0.0",
  author:"Talon",
  description:"A simple adjustable center reticle",
  enabled:true,
  config:[
    {key:"color",label:"Reticle color",type:"color",def:"#f06a78"},
    {key:"size",label:"Arm length",type:"number",def:7,min:3,max:14,step:1},
    {key:"gap",label:"Center gap",type:"number",def:3,min:1,max:9,step:1},
    {key:"thickness",label:"Line thickness",type:"number",def:2,min:1,max:4,step:1}
  ]
},function(api){
  var style=document.createElement("style");
  style.textContent=".crimson-reticle{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:2147483000;opacity:0;transition:opacity .12s}.crimson-reticle.active{opacity:1}.crimson-reticle .cr-reticle-center{position:relative;width:0;height:0}.crimson-reticle i{position:absolute;display:block;border-radius:1px;background:var(--cr-color);box-shadow:0 0 3px #000,0 0 5px var(--cr-color)}.crimson-reticle .up{width:var(--cr-thick);height:var(--cr-size);left:calc(var(--cr-thick)/-2);bottom:var(--cr-gap)}.crimson-reticle .down{width:var(--cr-thick);height:var(--cr-size);left:calc(var(--cr-thick)/-2);top:var(--cr-gap)}.crimson-reticle .left{height:var(--cr-thick);width:var(--cr-size);top:calc(var(--cr-thick)/-2);right:var(--cr-gap)}.crimson-reticle .right{height:var(--cr-thick);width:var(--cr-size);top:calc(var(--cr-thick)/-2);left:var(--cr-gap)}";
  document.head.appendChild(style);
  var overlay=document.createElement("div");
  overlay.className="crimson-reticle";
  overlay.innerHTML="<div class='cr-reticle-center'><i class='up'></i><i class='down'></i><i class='left'></i><i class='right'></i></div>";
  function applyConfig(){
    overlay.style.setProperty("--cr-color",String(api.config.get("color")||"#f06a78"));
    overlay.style.setProperty("--cr-size",String(api.config.get("size")||7)+"px");
    overlay.style.setProperty("--cr-gap",String(api.config.get("gap")||3)+"px");
    overlay.style.setProperty("--cr-thick",String(api.config.get("thickness")||2)+"px");
  }
  applyConfig();
  document.head.appendChild(overlay);
  EL.graphics.addOverlay(overlay);
  function show(){overlay.classList.add("active");}
  function hide(){overlay.classList.remove("active");}
  var offEnter=api.events.on("game:world-enter",show);
  var offExit=api.events.on("game:world-exit",hide);
  var offConfig=api.events.on("mod:config",function(ev){if(ev && ev.id===api.id)applyConfig();});
  if(EL.game.inWorld())show();
  return {onDisable:function(){
    if(offEnter)offEnter();
    if(offExit)offExit();
    if(offConfig)offConfig();
    EL.graphics.removeOverlay(overlay);
    overlay.remove();
    style.remove();
  }};
});
})();

