ackground:linear-gradient(#3a222a,#25171d)!important;color:#f0dfe1!important;border:1px solid #74404d!important;border-radius:3px!important;padding:6px 8px!important;font:10px ui-monospace,monospace!important}#el-modwin button:hover{background:linear-gradient(#63303c,#3a1d27)!important;border-color:#d15b6a!important}#el-modwin .el-mw-swatch{border:1px solid #a45b67!important}#el-modwin .el-mw-empty{color:#a98e95!important}#el-modwin .el-mw-foot{border-top:1px solid #4b3038!important;margin-top:6px!important;padding-top:9px!important}#el-modwin .el-mw-hint{color:#a88890!important}";
  document.head.appendChild(style);
  return {onDisable:function(){style.remove();}};
});
})();
